package dev.redstoneengineering.physics;
import dev.redstoneengineering.block.SerialDataLineBlock;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import java.util.*;
/** Bounded serial line propagation with frame/period/quality/utilization diagnostics. */
public final class SerialNetwork{private SerialNetwork(){}
 public static Set<BlockPos> collect(Level l,BlockPos start){Set<BlockPos>s=new HashSet<>();ArrayDeque<BlockPos>q=new ArrayDeque<>();if(!(l.getBlockState(start).getBlock() instanceof SerialDataLineBlock))return s;q.add(start);while(!q.isEmpty()&&s.size()<NetworkKernel.MAX_NODES){BlockPos p=q.removeFirst();if(!s.add(p))continue;for(Direction d:Direction.values()){BlockPos n=p.relative(d);if(l.hasChunkAt(n)&&l.getBlockState(n).getBlock() instanceof SerialDataLineBlock&&!s.contains(n))q.addLast(n);}}return s;}
 public static void drive(ServerLevel l,BlockPos start,int value,int period,boolean valid,int quality){Set<BlockPos>nodes=collect(l,start);int q=Math.max(0,Math.min(100,quality-nodes.size()/4));int now=(int)Math.min(Integer.MAX_VALUE,l.getGameTime());for(BlockPos p:nodes){InformationRuntime.write(l,"serial",p,value&255,Math.max(1,period),valid,q);int[]d=RuntimeIntStore.get(l,"serial_diag",p,8);d[0]++;d[1]=Math.max(1,period);d[2]=q;d[3]=nodes.size();if(d[4]>0)d[5]=Math.max(1,now-d[4]);d[4]=now;d[6]=valid?1:0;d[7]=d[5]==0?0:Math.min(100,(Math.max(1,period)*100)/Math.max(1,d[5]));l.updateNeighborsAt(p,l.getBlockState(p).getBlock());}NetworkKernel.recordScan(l,"serial",nodes.size(),nodes.size()>=NetworkKernel.MAX_NODES);}
 public static String diagnostics(Level l,BlockPos p){int[]d=RuntimeIntStore.get(l,"serial_diag",p,8);return "frames="+d[0]+" period="+d[1]+"t quality="+d[2]+"% nodes="+d[3]+" interarrival="+d[5]+"t utilization≈"+d[7]+"%";}
}
